//! C ABI for native frontends.
//!
//! The only crate frontends link against. Exposes opaque handles and plain C
//! functions; never leaks Rust types, never unwinds across the boundary. The
//! header `TesseraCore.h` is generated by `cbindgen` at build time and bundled
//! into `TesseraCore.xcframework` for the macOS app.

use std::ffi::{CStr, c_char};

/// Returns the core version as a NUL-terminated string.
///
/// The pointer is valid for the lifetime of the process and must not be freed.
#[unsafe(no_mangle)]
pub extern "C" fn tessera_version() -> *const c_char {
    static VERSION: &CStr =
        match CStr::from_bytes_with_nul(concat!(env!("CARGO_PKG_VERSION"), "\0").as_bytes()) {
            Ok(s) => s,
            Err(_) => panic!("version string contains NUL"),
        };
    VERSION.as_ptr()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn version_is_readable() {
        // SAFETY: tessera_version returns a valid NUL-terminated static string.
        let s = unsafe { CStr::from_ptr(tessera_version()) };
        assert_eq!(s.to_str().unwrap(), tessera_app_core::VERSION);
    }
}
